function BusWheel({ cx }: { cx: number }) {
  return (
    <g className="st-wheel">
      <circle cx={cx} cy="76" r="15" fill="#1a1a1a" />
      <g stroke="#ffffff" strokeWidth="2" strokeLinecap="round">
        <line x1={cx - 11} y1="76" x2={cx + 11} y2="76" />
        <line x1={cx} y1="65" x2={cx} y2="87" />
        <line x1={cx - 8} y1="68" x2={cx + 8} y2="84" />
        <line x1={cx + 8} y1="68" x2={cx - 8} y2="84" />
      </g>
      <circle cx={cx} cy="76" r="4.5" fill="#ffffff" />
    </g>
  );
}

/**
 * Sen Tur-designet lasteanimasjon: en buss som kjører langs en vei.
 * Brukes i stedet for "Laster..."-tekst/spinner der brukeren venter på
 * data (sidelast, tidsvindu-bytte, søk) — se claude.ai/design-prosjektet
 * "Sen Tur design forbedring".
 */
export function BusLoading({
  label = "Henter data",
  scale = 1,
  className,
}: {
  label?: string;
  scale?: number;
  className?: string;
}) {
  // Bredere enn originaldesignet ("dinosaur game"-stil) — mer vei synlig
  // samtidig i stedet for en trang, kortklippet rute. Høyden må være minst
  // bottom-offset (47) + busshøyde (95) + maks oppoverbevegelse i
  // st-busbob-animasjonen (~20px) = 162, ellers klippes bussetaket av
  // overflow-hidden i det høyeste punktet av "hoppet".
  const W = 480;
  const H = 172;
  return (
    <div
      className={cn("inline-block overflow-hidden", className)}
      style={{ width: W * scale, height: H * scale }}
    >
      <div style={{ width: W, height: H, transform: `scale(${scale})`, transformOrigin: "top left" }}>
        <div
          className="relative overflow-hidden"
          style={{ width: W, height: H }}
          role="img"
          aria-label={`${label} — buss som kjører`}
        >
          <svg
            width="2160"
            height="52"
            viewBox="0 0 2160 52"
            className="st-road absolute left-0"
            style={{ bottom: 30 }}
          >
            <path d={ROAD_PATH} fill="none" stroke="hsl(var(--muted-foreground))" strokeOpacity="0.35" strokeWidth="4" strokeLinecap="round" />
          </svg>
          <svg
            width="130"
            height="95"
            viewBox="0 0 130 95"
            className="st-bus absolute"
            style={{ left: "50%", bottom: 47, transformOrigin: "50% 96%" }}
          >
            <rect x="0" y="15" width="130" height="61" rx="12" fill="#2563eb" />
            <rect x="13" y="27" width="30" height="24" rx="3" fill="#ffffff" />
            <rect x="50" y="27" width="30" height="24" rx="3" fill="#ffffff" />
            <rect x="87" y="27" width="30" height="24" rx="3" fill="#ffffff" />
            <circle cx="122" cy="63" r="5" fill="#fde047" />
            <BusWheel cx={30} />
            <BusWheel cx={100} />
          </svg>
          <div
            className="absolute left-0 right-0 text-center font-semibold text-muted-foreground"
            style={{ bottom: 12, fontFamily: "'Nunito', Arial, sans-serif", fontSize: 13 }}
          >
            {label}
            <span className="st-dot" style={{ animationDelay: "0s" }}>.</span>
            <span className="st-dot" style={{ animationDelay: ".2s" }}>.</span>
            <span className="st-dot" style={{ animationDelay: ".4s" }}>.</span>
          </div>
        </div>
      </div>
    </div>
  );
}
